import { execSync } from "node:child_process";
import AxeBuilder from "@axe-core/playwright";
import { expect, test, type Page } from "@playwright/test";
import { selectLanguage } from "../helpers/header";
import { attachIdDocument, fillCompanyStep, samplePdf } from "../helpers/registration";

/*
 * REAL backend test, opt-in. Runs only when ROYAL_REAL_BACKEND=1, against an API-mode frontend
 * (PLAYWRIGHT_BASE_URL) and a local Laravel backend whose mail goes to Mailpit. Nothing is mocked:
 * the code is generated by Laravel, sent over SMTP, and read from the delivered email.
 * See docs/b2b-auth-integration.md for setup. Never point this at staging or production accounts.
 */
const enabled = process.env.ROYAL_REAL_BACKEND === "1";
const email = process.env.ROYAL_TEST_EMAIL ?? "";
const password = process.env.ROYAL_TEST_PASSWORD ?? "";
const companyId = process.env.ROYAL_TEST_COMPANY_ID ?? "";
const api = process.env.ROYAL_API_URL ?? "http://127.0.0.1:8000";
const mailpit = process.env.ROYAL_MAILPIT_URL ?? "http://127.0.0.1:8025";
const SESSION_KEY = "royal-travel.b2b-session.v1";

test.describe.configure({ mode: "serial" });
const localApi = /^https?:\/\/(127\.0\.0\.1|localhost)(:\d+)?\/?$/.test(api);
test.skip(!enabled, "Set ROYAL_REAL_BACKEND=1 with a local backend to run real authentication tests.");
// These tests register companies and sign in. They must never run against staging or production.
test.skip(enabled && !localApi, "ROYAL_API_URL must be a local backend; these tests create data.");

test.beforeEach(async ({ request }) => {
  // The backend allows 5 auth requests per minute per IP across all auth routes; a local reset
  // command (for example `docker exec royal-dev-php php artisan cache:clear`) keeps runs fast.
  if (process.env.ROYAL_RESET_THROTTLE) execSync(process.env.ROYAL_RESET_THROTTLE, { stdio: "ignore" });
  await request.delete(`${mailpit}/api/v1/messages`);
});

async function receivedCode(page: Page): Promise<string> {
  let code = "";
  await expect.poll(async () => {
    const list = await (await page.request.get(`${mailpit}/api/v1/messages`)).json();
    const message = list.messages?.find((item: { To: { Address: string }[] }) => item.To.some((to) => to.Address === email));
    if (!message) return "";
    const body = await (await page.request.get(`${mailpit}/api/v1/message/${message.ID}`)).json();
    expect(body.Subject).toBe("Royal Travel - Login Verification Code");
    code = body.Text.match(/\b(\d{6})\b/)?.[1] ?? "";
    return code;
  }, { timeout: 15000, message: "No verification email arrived in Mailpit" }).toMatch(/^\d{6}$/);
  return code;
}

async function submitCredentials(page: Page, values: { email?: string; password?: string; companyId?: string } = {}) {
  await page.locator("#username").fill(values.email ?? email);
  await page.locator("#password").fill(values.password ?? password);
  await page.locator("#company-id").fill(values.companyId ?? companyId);
  await page.locator("form.login-form button[type=submit]").click();
}

test("login, emailed code, /me, logout and revocation work against the real backend", async ({ page }) => {
  await page.goto("/login");
  await submitCredentials(page);
  await expect(page.getByRole("heading", { name: "Enter your verification code" })).toBeVisible();
  const code = await receivedCode(page);

  await page.locator("#login-code").fill(code);
  await page.getByRole("button", { name: "Verify and sign in" }).click();
  await expect(page).toHaveURL(/\/$/, { timeout: 15000 });

  const token: string = JSON.parse((await page.evaluate((key) => sessionStorage.getItem(key), SESSION_KEY))!).token;
  const me = await page.request.get(`${api}/api/v1/b2b/me`, { headers: { Accept: "application/json", Authorization: `Bearer ${token}` } });
  expect(me.status()).toBe(200);
  expect((await me.json()).data.company.id).toBe(companyId);

  await page.getByRole("button", { name: "Account menu" }).click();
  await expect(page.locator("[class*=accountIdentity]")).toContainText((await me.json()).data.company.name);

  // A reload confirms the session with the real /me before showing private pages.
  await page.goto("/bookings");
  await expect(page.getByRole("heading", { name: "My Bookings" })).toBeVisible();

  await page.getByRole("button", { name: "Account menu" }).click();
  await page.getByRole("button", { name: "Sign Out" }).click();
  await expect(page).toHaveURL(/\/welcome$/);
  expect(await page.evaluate((key) => sessionStorage.getItem(key), SESSION_KEY)).toBeNull();
  const after = await page.request.get(`${api}/api/v1/b2b/me`, { headers: { Accept: "application/json", Authorization: `Bearer ${token}` } });
  expect(after.status()).toBe(401);
});

test("an incorrect code is rejected by the backend", async ({ page }) => {
  await page.goto("/login");
  await submitCredentials(page);
  const code = await receivedCode(page);
  await page.locator("#login-code").fill(code === "000000" ? "111111" : "000000");
  await page.getByRole("button", { name: "Verify and sign in" }).click();
  await expect(page.locator("#login-code-error")).toHaveText("That code is incorrect or has expired.");
  expect(await page.evaluate((key) => sessionStorage.getItem(key), SESSION_KEY)).toBeNull();
});

test("an incorrect password sends no email", async ({ page }) => {
  await page.goto("/login");
  await submitCredentials(page, { password: "Wrong-Password-1!" });
  await expect(page.getByRole("status")).toHaveText("Incorrect email or password, or the account isn't activated yet.");
  expect((await (await page.request.get(`${mailpit}/api/v1/messages`)).json()).total).toBe(0);
});

test("a company the user doesn't belong to is refused", async ({ page }) => {
  await page.goto("/login");
  await submitCredentials(page, { companyId: "00000000-0000-4000-8000-000000000000" });
  await expect(page.getByRole("status")).toHaveText("This company isn't approved yet, or the account is inactive.");
  expect((await (await page.request.get(`${mailpit}/api/v1/messages`)).json()).total).toBe(0);
});

test("a network failure during verification is reported and nothing is stored", async ({ page, context }) => {
  await page.goto("/login");
  await submitCredentials(page);
  const code = await receivedCode(page);
  await context.setOffline(true);
  await page.locator("#login-code").fill(code);
  await page.getByRole("button", { name: "Verify and sign in" }).click();
  await expect(page.getByRole("alert")).toHaveText("We couldn't reach the sign-in service. Check your connection and try again.");
  await context.setOffline(false);
  expect(await page.evaluate((key) => sessionStorage.getItem(key), SESSION_KEY)).toBeNull();
});

test("Arabic, RTL, on a phone: the real flow signs in", async ({ page }) => {
  await page.setViewportSize({ width: 390, height: 844 });
  await page.goto("/login");
  await selectLanguage(page, "ar");
  await expect(page.locator("html")).toHaveAttribute("dir", "rtl");
  await submitCredentials(page);
  await expect(page.getByRole("heading", { name: "أدخل رمز التحقق" })).toBeVisible();
  expect((await new AxeBuilder({ page }).withTags(["wcag2a", "wcag2aa", "wcag21aa", "wcag22aa"]).analyze()).violations).toEqual([]);
  expect(await page.evaluate(() => document.documentElement.scrollWidth - document.documentElement.clientWidth)).toBeLessThanOrEqual(1);
  const code = await receivedCode(page);
  await page.locator("#login-code").fill(code);
  await page.getByRole("button", { name: "تحقق وسجّل الدخول" }).click();
  await expect(page).toHaveURL(/\/$/, { timeout: 15000 });
});

test("the profile page shows the real account from /me", async ({ page }) => {
  await page.goto("/login");
  await submitCredentials(page);
  const code = await receivedCode(page);
  await page.locator("#login-code").fill(code);
  await page.getByRole("button", { name: "Verify and sign in" }).click();
  await expect(page).toHaveURL(/\/$/, { timeout: 15000 });
  const token: string = JSON.parse((await page.evaluate((key) => sessionStorage.getItem(key), SESSION_KEY))!).token;
  const me = (await (await page.request.get(`${api}/api/v1/b2b/me`, { headers: { Accept: "application/json", Authorization: `Bearer ${token}` } })).json()).data;
  await page.goto("/profile");
  for (const value of [me.user.name, me.user.email, me.company.name]) await expect(page.locator("main")).toContainText(value);
  await expect(page.locator(".api-data-notice")).toHaveCount(0);
});

test("registration creates a pending company that can't sign in before approval", async ({ page }) => {
  const unique = Date.now().toString(36);
  await page.goto("/register/agency/company");
  await fillCompanyStep(page, { name: `Local Test Agency ${unique}`, registration: `LOCAL-${unique}` });
  await page.getByLabel("Full Name").fill("Local Test Contact");
  await page.getByLabel("Nationality").selectOption("EG");
  await page.getByLabel("ID Number").fill(`ID-${unique}`);
  await attachIdDocument(page);
  await page.getByPlaceholder("Enter phone number").fill("1001234567");
  await page.getByLabel("Email", { exact: false }).fill(`registration.${unique}@royal-dev.test`);
  await page.getByRole("button", { name: "Next", exact: true }).click();
  await page.getByLabel("Corporate", { exact: true }).check();
  await page.locator("#document-commercialRegistration").setInputFiles(samplePdf("cr.pdf"));
  await page.locator("#document-taxCertificate").setInputFiles(samplePdf("tax.pdf"));
  await page.getByRole("button", { name: "Next", exact: true }).click();
  const newPassword = `Local-Test-${unique}-9!`;
  await page.locator("#registration-password").fill(newPassword);
  await page.locator("#registration-password-confirmation").fill(newPassword);
  await page.getByRole("button", { name: "Submit registration" }).click();
  await expect(page.getByRole("heading", { name: "Registration Submitted!" })).toBeVisible();
  const newCompany = (await page.locator(".registration-success__id code bdi").textContent())!.trim();
  expect(newCompany).toMatch(/^[0-9a-f-]{36}$/);

  // A pending company is refused at sign-in, and no code is emailed.
  await page.goto("/login");
  await submitCredentials(page, { email: `registration.${unique}@royal-dev.test`, password: newPassword, companyId: newCompany });
  await expect(page.getByRole("status")).toHaveText("This company isn't approved yet, or the account is inactive.");
  expect((await (await page.request.get(`${mailpit}/api/v1/messages`)).json()).total).toBe(0);
});
